{
  "contract": "BadBunnyNFTS",
  "closure": {
    "site_function": "teamPayout",
    "site_call": ".transfer",
    "functions": [
      "<fallback>",
      "claimMintRewards",
      "mint",
      "teamPayout",
      "approvals",
      "setApproval"
    ],
    "justification": "Includes all functions that can affect _balanceDistributor and _ethBal, either directly or indirectly through external calls."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "claimMintRewards",
      "mint",
      "approvals",
      "setApproval"
    ],
    "nesting_bound": {
      "<fallback>": 1,
      "claimMintRewards": 1,
      "mint": 1,
      "approvals": 1,
      "setApproval": 1
    }
  },
  "phases": {
    "function": "teamPayout",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_transfer"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_transfer",
      "to_marker": "after_transfer"
    },
    "post": {
      "name": "post",
      "from_marker": "after_transfer",
      "to_marker": "end"
    },
    "linearization_point": "after_transfer"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of _ethBal in transit during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_balanceDistributor <= _ethBal + inFlight",
    "stable_formula": "_balanceDistributor <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "_balanceDistributor <= _ethBal",
    "rule": "The exposure invariant ensures that the target property holds even during reentrant calls."
  }
}
